/**
 * Errors surfaced across the FFI boundary.
 *
 * Kept separate from `EngineError` because UniFFI error types must be
 * `Clone` (git2 errors are not). Every variant carries `corruption`, set from
 * `EngineError::is_corruption_error`, so host apps can route corrupt-repo
 * failures into the repair flow.
 */
sealed class BridgeException: kotlin.Exception() {
    
    class Git(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    
    class Io(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    
    class Invalid(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    
    class Busy(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    
    class NotARepository(
        
        val `path`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "path=${ `path` }, corruption=${ `corruption` }"
    }
    
    class Unsupported(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    
    class Other(
        
        val `errorMessage`: kotlin.String, 
        
        val `corruption`: kotlin.Boolean
        ) : BridgeException() {
        override val message
            get() = "message=${ `errorMessage` }, corruption=${ `corruption` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BridgeException> {
        override fun lift(error_buf: RustBuffer.ByValue): BridgeException = FfiConverterTypeBridgeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeBridgeError : FfiConverterRustBuffer<BridgeException> {
    override fun read(buf: ByteBuffer): BridgeException {
        

        return when(buf.getInt()) {
            1 -> BridgeException.Git(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> BridgeException.Io(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            3 -> BridgeException.Invalid(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            4 -> BridgeException.Busy(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            5 -> BridgeException.NotARepository(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            6 -> BridgeException.Unsupported(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            7 -> BridgeException.Other(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BridgeException): ULong {
        return when(value) {
            is BridgeException.Git -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.Busy -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.NotARepository -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`path`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
            is BridgeException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterBoolean.allocationSize(value.`corruption`)
            )
        }
    }

    override fun write(value: BridgeException, buf: ByteBuffer) {
        when(value) {
            is BridgeException.Git -> {
                buf.putInt(1)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.Io -> {
                buf.putInt(2)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.Invalid -> {
                buf.putInt(3)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.Busy -> {
                buf.putInt(4)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.NotARepository -> {
                buf.putInt(5)
                FfiConverterString.write(value.`path`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.Unsupported -> {
                buf.putInt(6)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
            is BridgeException.Other -> {
                buf.putInt(7)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterBoolean.write(value.`corruption`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * How a credential should be resolved for a git operation.
 */
sealed class CredentialSource {
    
    /**
     * No credentials; only works for anonymous/public endpoints.
     */
    object None : CredentialSource()
    
    
    /**
     * HTTPS basic auth: PAT or OAuth token used as the password.
     */
    data class UserPass(
        val `username`: kotlin.String, 
        val `password`: kotlin.String) : CredentialSource()
        
    {
        

        companion object
    }
    
    /**
     * SSH keypair, loaded from memory (private key PEM text).
     */
    data class SshKey(
        val `username`: kotlin.String, 
        val `privateKey`: kotlin.String, 
        val `publicKey`: kotlin.String?, 
        val `passphrase`: kotlin.String?) : CredentialSource()
        
    {
        

        companion object
    }
    
    /**
     * Let libgit2 try its default paths (ssh agent, config, credential helpers).
     */
    object Default : CredentialSource()

    /**
     * GitHub OAuth access token — used as a bearer for HTTPS auth.
     */
    data class GitHubOAuth(
        val `token`: kotlin.String) : CredentialSource()

    /**
     * GitHub App installation token scoped to selected repositories.
     */
    data class GitHubAppInstallation(
        val `token`: kotlin.String) : CredentialSource()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCredentialSource : FfiConverterRustBuffer<CredentialSource>{
    override fun read(buf: ByteBuffer): CredentialSource {
        return when(buf.getInt()) {
            1 -> CredentialSource.None
            2 -> CredentialSource.UserPass(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> CredentialSource.SshKey(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            4 -> CredentialSource.Default
            5 -> CredentialSource.GitHubOAuth(
                FfiConverterString.read(buf),
                )
            6 -> CredentialSource.GitHubAppInstallation(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CredentialSource): ULong = when(value) {
        is CredentialSource.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CredentialSource.UserPass -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`username`)
                + FfiConverterString.allocationSize(value.`password`)
            )
        }
        is CredentialSource.SshKey -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`username`)
                + FfiConverterString.allocationSize(value.`privateKey`)
                + FfiConverterOptionalString.allocationSize(value.`publicKey`)
                + FfiConverterOptionalString.allocationSize(value.`passphrase`)
            )
        }
        is CredentialSource.Default -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CredentialSource.GitHubOAuth -> {
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
        is CredentialSource.GitHubAppInstallation -> {
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
    }

    override fun write(value: CredentialSource, buf: ByteBuffer) {
        when(value) {
            is CredentialSource.None -> {
                buf.putInt(1)
                Unit
            }
            is CredentialSource.UserPass -> {
                buf.putInt(2)
                FfiConverterString.write(value.`username`, buf)
                FfiConverterString.write(value.`password`, buf)
                Unit
            }
            is CredentialSource.SshKey -> {
                buf.putInt(3)
                FfiConverterString.write(value.`username`, buf)
                FfiConverterString.write(value.`privateKey`, buf)
                FfiConverterOptionalString.write(value.`publicKey`, buf)
                FfiConverterOptionalString.write(value.`passphrase`, buf)
                Unit
            }
            is CredentialSource.Default -> {
                buf.putInt(4)
                Unit
            }
            is CredentialSource.GitHubOAuth -> {
                buf.putInt(5)
                FfiConverterString.write(value.`token`, buf)
                Unit
            }
            is CredentialSource.GitHubAppInstallation -> {
                buf.putInt(6)
                FfiConverterString.write(value.`token`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





